ALPHABET_SIZE = 26
ORD_A_UPPER = ord('A')
ORD_A_LOWER = ord('a')
MIN_SHIFT = 0
MAX_SHIFT = ALPHABET_SIZE - 1
DEFAULT_SHIFT = 3
EMPTY_STRING = ""
SPACE_CHAR = ' '

def caesar_cipher_encrypt(text, shift):
    if not isinstance(text, str):
        raise TypeError("Input 'text' must be a string.")
    if not isinstance(shift, int):
        raise TypeError("Input 'shift' must be an integer.")
    if not (MIN_SHIFT <= shift <= ALPHABET_SIZE):
        shift %= ALPHABET_SIZE

    result_chars = []
    for char in text:
        if 'A' <= char <= 'Z':
            shifted_char_code = (ord(char) - ORD_A_UPPER + shift) % ALPHABET_SIZE + ORD_A_UPPER
            result_chars.append(chr(shifted_char_code))
        elif 'a' <= char <= 'z':
            shifted_char_code = (ord(char) - ORD_A_LOWER + shift) % ALPHABET_SIZE + ORD_A_LOWER
            result_chars.append(chr(shifted_char_code))
        else:
            result_chars.append(char)

    return EMPTY_STRING.join(result_chars)

