def get_average_movie_rating(movie_ratings: dict) -> dict:
    computed_averages = RETURN_DICTIONARY_INITIAL_STATE
    for movie_title, ratings_list in movie_ratings.items():
        if not ratings_list:
            computed_averages[movie_title] = DEFAULT_EMPTY_RATING_VALUE
            continue

        total_sum_of_ratings = SUMMATION_START_VALUE
        for rating_score in ratings_list:
            total_sum_of_ratings += rating_score

        number_of_ratings = len(ratings_list)
        if number_of_ratings == MINIMUM_RATING_COUNT:
            computed_averages[movie_title] = DEFAULT_EMPTY_RATING_VALUE
        else:
            average_rating = total_sum_of_ratings / number_of_ratings
            computed_averages[movie_title] = round(average_rating, RATING_DECIMAL_PLACES)
    return computed_averages

